// Unwrap the MCP JSON-RPC envelope into the goal object.
const text = $input.first().json.result.content[0].text;
const data = JSON.parse(text);
return { json: data.data ? data.data : data };

const goal = $('Parse Goal').first().json.goalItemById || {};
const grab = (n) => { try { const j = $(n).first().json; return (j && !j.error) ? j : {}; } catch (e) { return {}; } };
const rows = (n) => { const v = grab(n).values || []; if (v.length < 2) return [];
  const hdr = v[0].map(h => String(h).toLowerCase().trim());
  return v.slice(1).filter(r => r && r.some(c => String(c||'').trim() !== '')).map(r => { const o = {}; hdr.forEach((h,i) => o[h] = r[i]); return o; }); };
const pick = (o, names) => { for (const n of names) { const k = Object.keys(o).find(k => k.replace(/[^a-z]/g,'').includes(n)); if (k && o[k] != null && o[k] !== '') return o[k]; } return ''; };
const num = (c) => { const m = String(c).replace(/[,\s]/g,'').match(/(\d+(?:\.\d+)?)/); return m ? parseFloat(m[1]) : null; };

// ---- MEDIA: followers per platform + total ----
const social = grab('Get Social Analytics');
const order = ['instagram','x','youtube','tiktok','facebook','threads'];
const platKeys = Object.keys(social).filter(k => social[k] && typeof social[k] === 'object' && ('followers' in social[k]));
platKeys.sort((a,b) => ((order.indexOf(a)+1)||99) - ((order.indexOf(b)+1)||99));
const lines = [];
let totalFollowers = 0;
for (const p of platKeys) { const m = social[p];
  const f = num(m.followers); if (f != null) totalFollowers += f;
  lines.push('- ' + p + ': ' + (m.followers ?? '?') + ' followers; reach ' + (m.reach ?? 0) + ', views ' + (m.views ?? m.impressions ?? 0) + ', likes ' + (m.likes ?? 0) + ', comments ' + (m.comments ?? 0) + ', shares ' + (m.shares ?? 0)); }
const li = grab('Get LinkedIn Analytics');
const prof = (grab('Get LinkedIn Profile')).profile || {};
const liGrowth = (li.data || {}).followerGrowth || {};
const liFollowers = num(liGrowth.totalFollowers);
if (liFollowers != null) { totalFollowers += liFollowers;
  lines.push('- linkedin: ' + liFollowers + ' followers' + (liGrowth.changePercent != null ? (' (' + (liGrowth.changePercent >= 0 ? '+' : '') + liGrowth.changePercent + ' pct)') : '')); }
const conn = grab('Get LinkedIn Connections');
const connCount = (conn && conn.connectionCount != null) ? num(conn.connectionCount) : null;
lines.push('- linkedin connections: ' + (connCount != null ? connCount : 'unavailable (ConnectSafely returned no data - reconnect the LinkedIn account in the ConnectSafely dashboard)'));
const gaLine = (label, resp) => { try {
  const headers = (resp.metricHeaders || []).map(h => h.name);
  const r = (resp.rows && resp.rows[0]) ? resp.rows[0].metricValues.map(v => v.value) : null;
  if (!r) return '- GA ' + label + ' (28d): 0 users';
  const m = {}; headers.forEach((h,i) => m[h] = r[i]);
  return '- GA ' + label + ' (28d): ' + (m.totalUsers||0) + ' users, ' + (m.sessions||0) + ' sessions, ' + (m.screenPageViews||0) + ' pageviews';
} catch (e) { return '- GA ' + label + ': unavailable'; } };
const gaB = grab('Get GA Blog'), gaS = grab('Get GA Site');
if (gaB.metricHeaders || gaB.rows) lines.push(gaLine('blog.grvpanchal.me', gaB));
if (gaS.metricHeaders || gaS.rows) lines.push(gaLine('grvpanchal.me', gaS));
const analyticsText = lines.length ? ('Real cross-platform analytics:\n' + lines.join('\n')) : 'No live analytics available.';

// ---- LABOUR: Collaboration tab = developers working / collaborating / trained under me ----
const collab = rows('Get Collaboration');
const devLines = collab.map(r => '- ' + pick(r,['name']) + (pick(r,['domain']) ? (' [' + pick(r,['domain']) + ']') : '')
  + (pick(r,['status']) ? (' - ' + pick(r,['status'])) : '') + (pick(r,['comment','note']) ? (': ' + String(pick(r,['comment','note'])).slice(0,120)) : ''));
const devCount = collab.length;
const labourText = devCount
  ? ('Real labour roster (developers working, collaborating or trained under me - ' + devCount + '):\n' + devLines.join('\n'))
  : 'No developers recorded yet in the Collaboration sheet tab.';

// ---- TECH: ConnectSafely LinkedIn certifications PRIMARY (user has API plan, 2026-07-12);
// Certifications sheet tab is the fallback if the CS plan ever lapses again ----
const liCerts = prof.certifications || [];
const certRows = rows('Get Certifications');
const useLi = liCerts.length > 0;
const certCount = useLi ? liCerts.length : certRows.length;
const certLines = useLi
  ? liCerts.map(c => '- ' + (c.name||'') + (c.authority ? (' (' + c.authority + ')') : '') + (c.issueDate ? (', ' + c.issueDate) : ''))
  : certRows.map(c => '- ' + pick(c,['certification','name','title']) + (pick(c,['authority','issuer']) ? (' (' + pick(c,['authority','issuer']) + ')') : '') + (pick(c,['status']) ? (' - ' + pick(c,['status'])) : ''));
const certSource = useLi ? 'LinkedIn via ConnectSafely' : (certRows.length ? 'Certifications sheet tab' : 'none');
const techText = certCount
  ? ('Real certifications from ' + certSource + ' (' + certCount + '):\n' + certLines.join('\n'))
  : 'No certifications found (LinkedIn profile empty and Certifications sheet tab unfilled).';

// ---- CAPITAL: Applications tab -> income offered ----
const appRows = rows('Get Job Applications');
const apps = appRows.map(r => ({ company: pick(r,['company','employer','organi']), role: pick(r,['role','position','title','job','designation']),
  stage: String(pick(r,['stage','status','round','progress'])).toLowerCase(), comp: pick(r,['compensation','salary','ctc','offer','package','pay','lpa']) })).filter(a => a.company || a.role);
const offers = apps.filter(a => /offer|final|accept|select|hired|negoti|work/.test(a.stage));
const offerComps = offers.map(a => num(a.comp)).filter(v => v != null);
const allComps = apps.map(a => num(a.comp)).filter(v => v != null);
const incomeOffered = offerComps.length ? offerComps.reduce((s,v) => s+v, 0) : (allComps.length ? Math.max(...allComps) : 0);
const incomeLabel = offerComps.length ? (incomeOffered + ' (sum of ' + offerComps.length + ' offer/working-stage)') : (allComps.length ? (incomeOffered + ' (best in pipeline, no offers yet)') : 'n/a');
const capitalText = apps.length
  ? ('Real capital signal (job applications; money the market commits to my skills):\n'
     + '- Companies in pipeline: ' + apps.length + '\n'
     + '- Offer/working stage: ' + offers.length + (offers.length ? ('\n' + offers.map(a => '  - ' + a.company + (a.role ? (' (' + a.role + ')') : '') + (a.comp ? (' - ' + a.comp) : '')).join('\n')) : '')
     + '\n- Income offered: ' + incomeLabel)
  : 'Job-application data empty.';

// ---- MEASURABLE ENTITY TABLE ----
const entityTable = ['| Leverage | Measurable Entity | Value |', '|---|---|---|',
  '| Media | Total followers (' + (platKeys.join(' + ') || 'no platforms') + (liFollowers != null ? ' + linkedin' : '') + ') | ' + totalFollowers + ' |',
  '| Tech | Certifications (' + certSource + ') | ' + certCount + ' |',
  '| Labour | Developers working / collaborating / trained | ' + devCount + ' |',
  '| Capital | Income offered | ' + incomeLabel + ' |'].join('\n');

return { json: { goalItemById: goal, analyticsText, labourText, techText, capitalText, entityTable,
  entities: { totalFollowers, certifications: certCount, developers: devCount, incomeOffered: incomeLabel } } };

