const C = $('Build Context').first().json;
const sec = (n) => { try { const j = $(n).first().json;
  if (j && j.choices && j.choices[0]) return String(j.choices[0].message.content || '').trim();
  if (j && j.error) return '(agent error: ' + String(j.error.message || j.error).slice(0,120) + ')';
  return '(no output)'; } catch (e) { return '(did not run)'; } };
const report = ['# Leverage Report', '', C.entityTable, '',
  '## Media', sec('media agent'), '',
  '## Labour', sec('labour agent'), '',
  '## Capital', sec('capital agent'), '',
  '## Tech', sec('tech agent')].join('\n');
return [{ json: { goalId: $('Webhook').first().json.query.goal_id, newContribution: report, entities: C.entities } }];

